<?php
require_once '../includes/admin_auth.php';
$pdo->exec("CREATE TABLE IF NOT EXISTS agenda_estudos (id INT AUTO_INCREMENT PRIMARY KEY, usuario_id INT NOT NULL, titulo VARCHAR(120) NOT NULL, tema VARCHAR(100) NOT NULL, data_estudo DATE NOT NULL, hora_inicio TIME NOT NULL DEFAULT '16:00:00', duracao_minutos SMALLINT NOT NULL DEFAULT 30, observacoes VARCHAR(500) NULL, concluido TINYINT(1) NOT NULL DEFAULT 0, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_agenda_usuario_data (usuario_id, data_estudo), CONSTRAINT fk_agenda_usuario FOREIGN KEY (usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$monthInput=(string)($_GET['m']??date('Y-m'));$month=DateTimeImmutable::createFromFormat('!Y-m-d',$monthInput.'-01');if(!$month||$month->format('Y-m')!==$monthInput)$month=new DateTimeImmutable(date('Y-m-01'));$start=$month->format('Y-m-01');$end=$month->modify('last day of this month')->format('Y-m-d');
$requested=(string)($_GET['date']??'');$selected=DateTimeImmutable::createFromFormat('!Y-m-d',$requested);if(!$selected||$selected->format('Y-m-d')!==$requested||$selected->format('Y-m')!==$month->format('Y-m'))$selected=$month->format('Y-m')===date('Y-m')?new DateTimeImmutable('today'):$month;$selectedKey=$selected->format('Y-m-d');
$stmt=$pdo->prepare("SELECT a.data_estudo,COUNT(*) total,SUM(a.concluido=1) concluidas FROM agenda_estudos a JOIN usuarios u ON u.id=a.usuario_id AND u.tipo='aluno' WHERE a.data_estudo BETWEEN ? AND ? GROUP BY a.data_estudo");$stmt->execute([$start,$end]);$counts=[];foreach($stmt->fetchAll() as $row)$counts[$row['data_estudo']]=$row;
$stmt=$pdo->prepare("SELECT a.titulo,a.tema,a.data_estudo,a.hora_inicio,a.duracao_minutos,a.concluido,u.nome aluno_nome FROM agenda_estudos a JOIN usuarios u ON u.id=a.usuario_id WHERE u.tipo='aluno' AND a.data_estudo=? ORDER BY a.hora_inicio,u.nome");$stmt->execute([$selectedKey]);$dayEvents=$stmt->fetchAll();$stmt=$pdo->prepare("SELECT COUNT(*) FROM agenda_estudos a JOIN usuarios u ON u.id=a.usuario_id WHERE u.tipo='aluno' AND a.data_estudo BETWEEN ? AND ?");$stmt->execute([$start,$end]);$total=(int)$stmt->fetchColumn();$studentCount=(int)$pdo->query("SELECT COUNT(*) FROM usuarios WHERE tipo='aluno'")->fetchColumn();
$weekday=(int)$month->format('N');$gridStart=$month->modify('-'.($weekday-1).' days');$gridDays=(int)ceil(($weekday-1+(int)$month->format('t'))/7)*7;$previous=$month->modify('-1 month');$next=$month->modify('+1 month');$monthNames=[1=>'janeiro',2=>'fevereiro',3=>'março',4=>'abril',5=>'maio',6=>'junho',7=>'julho',8=>'agosto',9=>'setembro',10=>'outubro',11=>'novembro',12=>'dezembro'];$weekdays=['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'];
?>
