<section class="teacher-agenda-stats" aria-label="Resumo do mês"><article><span>Planos neste mês</span><strong><?= $total ?></strong></article><article><span>Alunos cadastrados</span><strong><?= $studentCount ?></strong></article><article><span>Dia selecionado</span><strong><?= count($dayEvents) ?></strong></article></section>
<div class="teacher-agenda-layout"><section class="teacher-calendar-card" aria-label="Calendário mensal"><header class="teacher-calendar-toolbar"><div><span class="teacher-agenda-kicker">CALENDÁRIO DA TURMA</span><h2><?= escape($monthNames[(int)$month->format('n')]) ?> <span><?= $month->format('Y') ?></span></h2></div><nav aria-label="Navegar meses"><a href="?m=<?= $previous->format('Y-m') ?>" aria-label="Mês anterior">‹</a><a class="teacher-today" href="?m=<?= date('Y-m') ?>&amp;date=<?= date('Y-m-d') ?>">Hoje</a><a href="?m=<?= $next->format('Y-m') ?>" aria-label="Próximo mês">›</a></nav></header><div class="teacher-calendar-grid teacher-weekdays"><?php foreach($weekdays as $day): ?><span><?= $day ?></span><?php endforeach; ?></div><div class="teacher-calendar-grid teacher-days"><?php for($i=0;$i<$gridDays;$i++):$day=$gridStart->modify('+'.$i.' days');$key=$day->format('Y-m-d');$info=$counts[$key]??null;$outside=$day->format('m')!==$month->format('m'); ?><a class="teacher-day <?= $outside?'is-outside':'' ?> <?= $key===date('Y-m-d')?'is-today':'' ?> <?= $key===$selectedKey?'is-selected':'' ?> <?= $info?'has-plans':'' ?>" href="?m=<?= $day->format('Y-m') ?>&amp;date=<?= $key ?>" aria-label="<?= $day->format('d/m/Y') ?>, <?= (int)($info['total']??0) ?> planos"><span><?= $day->format('j') ?></span><?php if($info): ?><small><?= (int)$info['total'] ?> <?= (int)$info['total']===1?'plano':'planos' ?></small><?php endif; ?></a><?php endfor; ?></div><footer class="teacher-calendar-legend"><span><i></i> Há sessões planejadas</span><span><b></b> Hoje</span></footer></section>
<aside class="teacher-day-panel"><header><div><span class="teacher-agenda-kicker">PLANOS DA TURMA</span><h2><?= $selected->format('d') ?> de <?= escape($monthNames[(int)$selected->format('n')]) ?></h2></div><strong><?= count($dayEvents) ?></strong></header><?php if($dayEvents): ?><div class="teacher-day-list"><?php foreach($dayEvents as $event): ?><article class="teacher-day-event"><span class="teacher-event-time"><?= substr($event['hora_inicio'],0,5) ?></span><div><strong><?= escape($event['titulo']) ?></strong><span><?= escape($event['tema']) ?> · <?= (int)$event['duracao_minutos'] ?> min</span><small>Aluno: <?= escape($event['aluno_nome']) ?></small></div><span class="teacher-event-status <?= (int)$event['concluido']?'is-done':'' ?>"><?= (int)$event['concluido']?'Concluída':'Planejada' ?></span></article><?php endforeach; ?></div><?php else: ?><div class="teacher-day-empty"><span>▦</span><strong>Nenhuma sessão planejada</strong><p>Escolha outra data no calendário para acompanhar os planos dos alunos.</p></div><?php endif; ?></aside></div><p class="teacher-agenda-note">Aqui você acompanha o planejamento de estudos da turma. As observações pessoais de cada aluno continuam privadas.</p></div></main></div><script src="../js/script.js?v=20261010-brand-agenda"></script></body></html>
